class Solution {
    public int[] replaceElements(int[] arr){
        int maximum=-1;
        for(int i=arr.length-1;i>=0;i--){
            int original=arr[i];
            arr[i]=maximum;
            maximum=Math.max(maximum,original);
        }
        return arr;
    }
}

code.kotlin:
class Solution {
    fun replaceElements(arr:IntArray):IntArray{
        var maximum=-1;
        for(i in arr.lastIndex downTo 0){
            val original=arr[i];
            arr[i]=maximum;
            maximum=maxOf(maximum,original)
        };
        return arr
    }
}

